ROOT=[dict(id='C1655',meaning='飞；飞走',core='vol-：飞走、留不住，进而说挥发快或变化难稳定。',image='水面上的一点东西散入空气；价格或情绪也像上下飞动，难以停在原处。',intro='拉丁 volare 是飞，volatilis 是会飞、转瞬即逝的。volatile 在英语里把画面延伸到易挥发、易变；volatility 是这种性质，nonvolatile 则是否定。计算机借“留不住”描述断电后数据是否保留。',forms='volatile 是经法语进入的完整借词；volatility 和 nonvolatile 是英语派生。这一页的 vol- 与“意愿”的拉丁 velle 以及“卷”的 volvere 要分开。',branches=[['容易散去或变化','volatile'],['变化与挥发的程度','volatility'],['不易散去；断电仍能保留','nonvolatile']],contrasts='易挥发不自动等于易燃易爆；波动大不等于只跌不涨；非易失性不等于不能改写或永不损坏。',practice='分别用液体、价格和计算机存储解释 volatile，注意同一画面在不同领域的具体意思。',words=[w for w in r['family']if w in keep],exclude=excluded,sources=['https://www.etymonline.com/word/volatile','https://www.etymonline.com/word/volatility','https://www.nccoe.nist.gov/publication/1800-30/VolB/vol-b-appendix.html'])]
